Constructors:
-- Array-style constructor
local colors = {"red", "green", "blue"}
print(colors[1])  -- red (1-indexed!)

-- Key-value constructor
local point = {x = 10, y = 20}
print(point.x)    -- 10
print(point["y"]) -- 20

-- Mixed constructor
local mixed = {"hello", key = "world", 42}

-- Nested constructors
local matrix = {
    {1, 2, 3},
    {4, 5, 6},
    {7, 8, 9}
}
print(matrix[2][3])  -- 6

Nested Tables:
-- Nested records
local student = {
    name = "Bob",
    grades = {
        math = 95,
        science = 88,
        history = 92
    },
    address = {
        city = "Portland",
        state = "OR"
    }
}

print(student.grades.math)        -- 95
print(student["address"]["city"]) -- Portland

-- Multi-dimensional array
local matrix = {}
for i = 1, 3 do
    matrix[i] = {}
    for j = 1, 3 do
        matrix[i][j] = i * j
    end
end

print(matrix[2][3])  -- 6

Table Manipulation Library:
local t = {3, 1, 4, 1, 5, 9}

-- Insert
local tab = {1, 2, 3}
table.insert(tab, 4)     -- end: {1,2,3,4}
table.insert(tab, 2, 99) -- pos: {1,99,2,3,4}

-- Remove
local removed = table.remove(tab, 2)
print("Removed:", removed)  -- 99

-- Sort
local names = {"Charlie", "Alice", "Bob"}
table.sort(names)

-- Custom sort (descending)
table.sort(names, function(a, b) return a > b end)

-- Concat (fast string joining)
local parts = {"hello", "world", "lua"}
print(table.concat(parts, ", "))  -- "hello, world, lua"

-- Pack/unpack
local args = table.pack(1, 2, 3, 4)
print(args.n)  -- 4
print(table.unpack(args))  -- 1 2 3 4

-- Move elements
local src = {1, 2, 3, 4, 5}
local dst = {}
table.move(src, 1, 3, 1, dst)
print(dst[1], dst[2], dst[3])  -- 1 2 3

Arithmetic Metamethods:
local Vector = {}
Vector.__index = Vector

function Vector:new(x, y)
    return setmetatable({x = x, y = y}, Vector)
end

function Vector.__add(a, b)
    return Vector:new(a.x + b.x, a.y + b.y)
end

function Vector.__sub(a, b)
    return Vector:new(a.x - b.x, a.y - b.y)
end

function Vector.__tostring(self)
    return "(" .. self.x .. ", " .. self.y .. ")"
end

function Vector.__mul(a, b)
    if type(b) == "number" then
        return Vector:new(a.x * b, a.y * b)
    elseif type(a) == "number" then
        return Vector:new(b.x * a, b.y * a)
    end
end

local v1 = Vector:new(3, 4)
local v2 = Vector:new(1, 2)
print(v1 + v2)  -- (4, 6)
print(v1 * 3)   -- (9, 12)

